head.b:skin:
/* ==================================================
   DESIGN PARAMETERS
   ================================================== */

:root {

  /* --------------------------------------------------
     Colors
     -------------------------------------------------- */

  --color-page: #f1f1f1;
  --color-surface: #fcfcfc;
  --color-paper: #fcfcfc;

  --color-text: #202122;
  --color-muted: #54595d;

  --color-link: #0645ad;
  --color-link-hover: #0645ad;

  --color-border: #a2a9b1;
  --color-border-light: #c8ccd1;

  --color-code: #f8f9fa;

  --color-table-header: #eaecf0;
  --color-table-alt: #f8f9fa;

  --color-hover: #eaecf0;


  /* --------------------------------------------------
     Layout
     -------------------------------------------------- */

  --site-max-width: 1280px;
  --search-max-width: 360px;

  --contents-width: 240px;
  --article-max-width: 900px;

  --layout-gap: 64px;

  --layout-padding-top: 72px;
  --layout-padding-right: 48px;
  --layout-padding-bottom: 72px;
  --layout-padding-left: 48px;


  /* --------------------------------------------------
     Base Typography
     -------------------------------------------------- */

  --base-font-size: 16px;
  --base-line-height: 1.6;

  --body-font-weight: 500;

  --body-font-family:
    "メイリオ",
    Meiryo,
    "ヒラギノ角ゴ Pro W3",
    Hiragino Kaku Gothic Pro,
    "ＭＳ Ｐゴシック",
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    "Noto Sans JP",
    "Hiragino Sans",
    "Yu Gothic",
    sans-serif;

}



/* ==================================================
   BASE
   ================================================== */

* {
  box-sizing: border-box;
}

html {
  font-size: var(--base-font-size);
}

body {
  margin: 0;
  background: var(--color-page);
  color: var(--color-text);

  font-family: var(--body-font-family);
  font-size: var(--base-font-size);
  font-weight: var(--body-font-weight);
  line-height: var(--base-line-height);
}

a {
  color: var(--color-link);
  text-decoration: none;
}

a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}



/* ==================================================
   MAIN LAYOUT
   ================================================== */

.site-layout {
  max-width: var(--site-max-width);

  margin: 0 auto;

  display: grid;

  grid-template-columns:
    var(--contents-width)
    minmax(0, 1fr);

  gap: var(--layout-gap);

  padding:
    var(--layout-padding-top)
    var(--layout-padding-right)
    var(--layout-padding-bottom)
    var(--layout-padding-left);

  background: var(--color-surface);

  min-height: calc(100vh - 180px);
}



/* ==================================================
   RESPONSIVE
   ================================================== */


/* --------------------------------------------------
   Article Gallery - Mobile
   -------------------------------------------------- */

@media (max-width: 800px) {

  .article-gallery-item {
    flex-basis: 180px;
  }

  .article-gallery-item img {
    height: 140px;
  }

}

@media (max-width: 500px) {

  .article-gallery-item {
    flex-basis: 160px;
  }

  .article-gallery-item img {
    height: 130px;
  }

}



/* --------------------------------------------------
   Global Mobile Layout
   -------------------------------------------------- */

@media (max-width: 800px) {

  .header-inner {
    flex-wrap: wrap;
  }

  .site-layout {
    display: block;

    padding: var(--mobile-layout-padding);
  }

  .contents {
    position: static;

    margin-bottom: var(--mobile-contents-margin-bottom);

    padding: var(--mobile-contents-padding);

    border: 1px solid var(--color-border-light);

    background: var(--color-surface);
  }

  .article-title {
    font-size: var(--mobile-article-title-size);
  }

  .home-main {
    max-width: none;
  }

  .infobox {
    float: none;

    width: 100%;

    margin:
      0
      0
      var(--mobile-infobox-margin-bottom);
  }

  .article-body pre[class*="language-"] {
    padding: var(--mobile-code-padding);
  }

  .article-body pre[class*="language-"] > code {
    font-size: var(--mobile-code-font-size);
  }

}

