/* ===================================
Index Abstract / Top Image JS
====================================== */

/* ===================================
Index Article Settings
====================================== */

const INDEX_ABSTRACT_MAX_LENGTH = 200;


document.addEventListener("DOMContentLoaded", function () {

  document.querySelectorAll(
    ".article-list-item"
  ).forEach(function (item) {

    const source =
      item.querySelector(
        ".index-article-source"
      );

    const abstract =
      item.querySelector(
        ".article-list-abstract"
      );

    if (!source) {
      return;
    }

    /* ===================================
    Abstract
    ====================================== */

    if (abstract) {

      const headings =
        Array.from(
          source.querySelectorAll("h2")
        );

      const abstractHeading =
        headings.find(function (heading) {
          return heading.textContent.trim()
            .toLowerCase() === "abstract";
        });

      if (abstractHeading) {

        let element =
          abstractHeading.nextElementSibling;

        const parts = [];

        while (
          element &&
          element.tagName.toLowerCase() !== "h2"
        ) {

          /*
           * 図・画像はAbstract本文から除外
           */
          if (
            !element.matches(".article-target") &&
            !element.matches(".article-image") &&
            !element.querySelector("img")
          ) {
            parts.push(
              element.textContent
            );
          }

          element =
            element.nextElementSibling;
        }

        /*
         * Abstractを1つの文章にまとめる
         * 改行・連続空白を整理
         */
        let text =
          parts.join(" ")
            .replace(/\s+/g, " ")
            .trim();

        /*
         * Abstractを120文字程度に短縮
         */
        if (text.length > INDEX_ABSTRACT_MAX_LENGTH) {
          text =
            text.substring(
              0,
              INDEX_ABSTRACT_MAX_LENGTH
            ).trim() +
            "…";
        }

        if (text) {

          abstract.textContent =
            text;

        } else {

          abstract.remove();

        }

      } else {

        abstract.remove();

      }
    }

    /* ===================================
    Top Image
    ====================================== */

    const topImage =
      source.querySelector(
        "img[data-top-image='true']"
      );

    if (!topImage) {
      return;
    }

    const imageBox =
      document.createElement("div");

    imageBox.className =
      "article-list-thumbnail";

    const image =
      topImage.cloneNode(true);

    imageBox.appendChild(image);

    item
      .querySelector(
        ".article-list-thumbnail-container"
      )
      .appendChild(imageBox);
  });

});

