/* ===================================
  PopularPostsAbstract JS
  人気の記事にAbstractを表示
  ====================================== */

document.addEventListener("DOMContentLoaded", function () {

  const popularPostsList =
    document.querySelectorAll(".popular-posts");

  if (!popularPostsList.length) return;

  popularPostsList.forEach(function (popularPosts) {

    const items =
      popularPosts.querySelectorAll("li");

    items.forEach(function (item) {

      const link =
        item.querySelector(".item-title a");

      if (!link) return;

      const url = link.href;

      if (!url) return;

      fetch(url)
        .then(function (response) {
          return response.text();
        })
        .then(function (html) {

          const parser =
            new DOMParser();

          const doc =
            parser.parseFromString(
              html,
              "text/html"
            );

          const headings =
            doc.querySelectorAll("h2, h3");

          for (const heading of headings) {

            if (
              heading.textContent
                .trim()
                .toLowerCase() === "abstract"
            ) {

              let abstract =
                heading.nextElementSibling;

              if (!abstract) return;

              const snippet =
                document.createElement("div");

              snippet.className =
                "popular-post-abstract";

              snippet.textContent =
                abstract.textContent.trim();

              const oldSnippet =
                item.querySelector(
                  ".item-snippet"
                );

              if (oldSnippet) {

                oldSnippet.replaceWith(
                  snippet
                );

              } else {

                item.appendChild(
                  snippet
                );

              }

              break;
            }
          }
        })
        .catch(function () {

          /* Abstract取得失敗時は既存表示を維持 */

        });

    });

  });

});

