document.addEventListener("DOMContentLoaded", function () {

  const refs =
    document.querySelectorAll("article-ref");

  if (!refs.length) return;

  refs.forEach(function (ref) {

    const url =
      ref.getAttribute("url");

    if (!url) return;

    fetch(url)
      .then(function (response) {
        return response.text();
      })
      .then(function (html) {

        const parser =
          new DOMParser();

        const doc =
          parser.parseFromString(
            html,
            "text/html"
          );

        /* =========================
           タイトル
           ========================= */

        const titleElement =
          doc.querySelector(
            ".article-title"
          );

        const title =
          titleElement
            ? titleElement.textContent.trim()
            : "";

        /* =========================
           Abstract
           ========================= */

        let abstract = "";

        const headings =
          doc.querySelectorAll("h2, h3");

        for (const heading of headings) {

          if (
            heading.textContent
              .trim()
              .toLowerCase() === "abstract"
          ) {

            const abstractElement =
              heading.nextElementSibling;

            if (abstractElement) {

              abstract =
                abstractElement
                  .textContent
                  .trim();

            }

            break;
          }
        }

		/* =========================
           メタデータ
           ========================= */

        let meta = "";

        const metaElement =
          doc.querySelector(".article-meta");

        if (metaElement) {

          meta =
            metaElement.textContent
              .replace(/\s+/g, " ")
              .trim();

        }

        /* =========================
           画像
           ========================= */

        let imageUrl = "";

        const imageElement =
          doc.querySelector(
            ".article-body img"
          );

        if (imageElement) {

          imageUrl =
            imageElement.getAttribute("src") || "";

        }

        /* =========================
           カード生成
           ========================= */

        const card =
          document.createElement("div");

        card.className =
          "article-ref-card";

        card.setAttribute(
          "data-type",
          "article"
        );

        card.setAttribute(
          "data-label",
          ref.getAttribute("data-label")
        );


        /* =========================
           ヘッダー
           ========================= */

        const header =
          document.createElement("div");

        header.className =
          "article-ref-header";

        card.appendChild(
          header
        );


        /* =========================
           ボディ
           ========================= */

        const body =
          document.createElement("div");

        body.className =
          "article-ref-body";

        card.appendChild(
          body
        );


        /* =========================
           画像
           ========================= */

        if (imageUrl) {

          const imageLink =
            document.createElement("a");

          imageLink.href =
            url;

          imageLink.target =
            "_self";

          imageLink.className =
            "article-ref-image-link";

          const image =
            document.createElement("img");

          image.className =
            "article-ref-image";

          image.src =
            imageUrl;

          image.alt =
            title;

          imageLink.appendChild(
            image
          );

          body.appendChild(
            imageLink
          );

        }


        /* =========================
           情報エリア
           ========================= */

        const info =
          document.createElement("div");

        info.className =
          "article-ref-info";

        body.appendChild(
          info
        );


        /* =========================
           タイトル
           ========================= */

        const link =
          document.createElement("a");

        link.href =
          url;

        link.textContent =
          title || url;

        link.className =
          "article-ref-title";

        info.appendChild(
          link
        );


        /* =========================
           メタデータ
           ========================= */

        if (meta) {

          const metaElement =
            document.createElement("div");

          metaElement.className =
            "article-ref-meta";

          metaElement.textContent =
            meta;

          info.appendChild(
            metaElement
          );

        }


        /* =========================
           Abstract
           ========================= */

        if (abstract) {

          const abstractElement =
            document.createElement("div");

          abstractElement.className =
            "article-ref-abstract";

          abstractElement.textContent =
            abstract;

          info.appendChild(
            abstractElement
          );

        }


        /* =========================
           元のarticle-refを置換
           ========================= */

        ref.replaceWith(
          card
        );

      })
      .catch(function () {

        /* 参照失敗時は何もしない */

      });

  });

});

