/* ===================================
   FeaturedPostAbstract JS
   注目記事のAbstractを全文表示
   =================================== */

document.addEventListener("DOMContentLoaded", function () {

  const featuredPost =
    document.querySelector("#FeaturedPost1");

  if (!featuredPost) return;


  const titleLink =
    featuredPost.querySelector(
      ".post-summary h3 a"
    );

  if (!titleLink) return;


  const url =
    titleLink.href;

  if (!url) return;


  fetch(url)
    .then(function (response) {

      return response.text();

    })
    .then(function (html) {

      const parser =
        new DOMParser();

      const doc =
        parser.parseFromString(
          html,
          "text/html"
        );


      const headings =
        doc.querySelectorAll("h2, h3");


      for (const heading of headings) {

        if (
          heading.textContent
            .trim()
            .toLowerCase() !== "abstract"
        ) {

          continue;

        }


        const abstract =
          heading.nextElementSibling;


        if (!abstract) {
          return;
        }


        const target =
          featuredPost.querySelector(
            ".featured-post-abstract"
          );


        if (!target) {
          return;
        }


        target.textContent =
          abstract.textContent.trim();


        break;

      }

    })
    .catch(function () {

      /* Abstract取得失敗時は
         Blogger標準の表示を維持 */

    });

});

